def rel_prefix(depth):
    return "../" * depth


def header(depth=0):
    p = rel_prefix(depth)
    return f'''<a class="skip-link" href="#main">Skip to content</a><div class="fts-status">Live pre-launch preview · checkout intentionally locked · <a href="{p}index.html#launch-gates">see launch gates</a></div><header class="preview-header"><nav class="preview-nav" aria-label="Primary"><a class="preview-brand" href="{p}index.html">First Thread Studio<small>Small projects · real finishes</small></a><button class="preview-menu" aria-expanded="false" aria-label="Open navigation">Menu</button><div class="preview-links"><a href="{p}shop.html">Shop designs</a><a href="{p}pages/how-it-works.html">How it works</a><a href="{p}pages/beginner-help.html">Beginner help</a><a href="{p}pages/our-story.html">Our story</a><a href="{p}cart.html">Cart · 0</a></div></nav></header>'''


def footer(depth=0):
    p = rel_prefix(depth)
    return f'''<footer class="preview-footer"><div class="fts-shell"><div class="preview-footer__grid"><div><h2>First Thread Studio</h2><p>Original mini needlepoint projects designed around a true beginner's first finish.</p><p><strong>Preview only:</strong> no payment is accepted.</p></div><div><h3>Start here</h3><a href="{p}shop.html">Founding designs</a><a href="{p}pages/how-it-works.html">How it works</a><a href="{p}pages/beginner-help.html">Beginner help</a><a href="{p}pages/faq.html">FAQ</a></div><div><h3>Store information</h3><a href="{p}pages/founding-drop-policy.html">Founding drop policy</a><a href="{p}pages/shipping-returns.html">Shipping & returns</a><a href="{p}pages/contact.html">Contact</a><a href="mailto:firstthread-studio@agentmail.to">Email us</a></div></div><div class="preview-footer__legal">© 2026 First Thread Studio · working brand name pending legal clearance · all current product images are digital visualizations.</div></div></footer><div class="preview-toast" role="status" aria-live="polite"></div><script src="{p}assets/preview.js"></script>'''


def doc(title, body, depth=0, description="Original beginner mini needlepoint kits."):
    p = rel_prefix(depth)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} · First Thread Studio</title><meta name="description" content="{html.escape(description)}"><link rel="stylesheet" href="{p}assets/first-thread.css"><link rel="stylesheet" href="{p}assets/preview.css"><link rel="icon" href="{p}assets/first-thread-logo.svg"></head><body class="preview-body">{header(depth)}<main id="main">{body}</main>{footer(depth)}</body></html>'''


def card(product, depth=0):
    p = rel_prefix(depth)
    return f'''<a class="fts-product-card" href="{p}products/{product['handle']}.html"><div class="fts-product-card__media"><img src="{p}assets/{product['images'][0]}" alt="Digital visualization of the planned {html.escape(product['short_title'])} kit; final materials may vary" width="1600" height="1600" loading="lazy"><span class="fts-product-card__badge">{html.escape(product['badge'])}</span></div><div class="fts-product-card__body"><h3>{html.escape(product['short_title'])}</h3><span class="fts-product-card__price">${product['price']}</span><p>{html.escape(product['one_line'])}</p></div></a>'''

